CREATE DATABASE IF NOT EXISTS `noxara_Jaka22` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `noxara_Jaka22`;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) UNIQUE,email VARCHAR(120) UNIQUE,phone VARCHAR(30) UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') DEFAULT 'user',status ENUM('active','blocked') DEFAULT 'active',referral_code VARCHAR(30) UNIQUE NULL,referred_by BIGINT UNSIGNED NULL,created_at DATETIME,updated_at DATETIME,INDEX(referred_by)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,created_at DATETIME,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,code VARCHAR(100) NULL,status VARCHAR(40) DEFAULT 'active',amount DECIMAL(18,2) DEFAULT 0,data JSON NULL,created_at DATETIME,updated_at DATETIME,INDEX(user_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
