CREATE TABLE ledger_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,type VARCHAR(60),direction ENUM('debit','credit'),amount DECIMAL(18,2),balance_type VARCHAR(40),reference_type VARCHAR(60),reference_id VARCHAR(80),idempotency_key VARCHAR(120) UNIQUE NULL,description VARCHAR(255),meta JSON NULL,status VARCHAR(40) DEFAULT 'success',created_at DATETIME,updated_at DATETIME,INDEX(user_id),INDEX(type),INDEX(reference_type,reference_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
